  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Vrai. L'achat de la résidence principale figure parmi les cas de déblocage anticipé du PER individuel pour les versements volontaires. Le conseiller le rappelle en précisant que c'est le seul cas hors accident de la vie (leçon 1).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q03$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$mecanisme-et-disponibilite$academy_seed$, $academy_seed$Cas fictif. À l'ouverture d'un PER, un client de 55 ans hésite entre une sortie en capital et une sortie en rente. Quelle attitude est conforme à la méthode enseignée dans ce parcours ?$academy_seed$, $academy_seed$["Recommander la rente, plus sûre dans tous les cas","Recommander le capital, plus avantageux dans tous les cas","Expliquer que la sortie peut être en capital, en rente ou mixte, et relier ce choix à ses objectifs de vie et à ses autres revenus à la retraite dans l'étude","Reporter la question, elle n'a aucune importance au moment de l'ouverture"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$La loi permet une sortie en capital, en rente ou mixte. Le choix dépend des objectifs de vie et des autres revenus du client, et il se réfléchit dès l'ouverture, car une option définitive pour la rente ferme la sortie en capital (leçon 1).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q04$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$fiscalite-a-verifier$academy_seed$, $academy_seed$Cas fictif. Une cliente salariée imposée dans la tranche à 41 % vous demande son plafond de déduction PER. Quelle démarche adoptez-vous ?$academy_seed$, $academy_seed$["Appliquer 10 % de son salaire de mémoire et lui donner le chiffre en séance","Reprendre le montant affiché sur la brochure d'un assureur","Lire avec elle la ligne « plafond épargne retraite » de son dernier avis d'imposition, reports compris, et citer la source officielle datée dans l'étude","Retenir le plafond de son conjoint, plus élevé"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Le plafond se lit sur l'avis d'imposition, reports des trois années précédentes compris, et se vérifie sur la source officielle datée. Un chiffre de mémoire ou tiré d'un support commercial n'est jamais présenté comme acquis (leçon 2).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q05$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$fiscalite-a-verifier$academy_seed$, $academy_seed$Cas fictif. Un client a déduit ses versements PER pendant quinze ans. À la retraite, il choisit une sortie en capital. La part du capital correspondant à ses versements ne sera soumise à aucun impôt sur le revenu.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 2)
