  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La méthode place la protection des revenus et l'épargne disponible avant l'épargne bloquée. Le PER vient ensuite, calibré sur la capacité d'épargne réelle. Remplacer le PER par une autre enveloppe ne règle pas l'absence de sécurité (leçon 3).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
